// Street, park, river, and lake shapes are bundled so a guess never leaves the browser.
// OpenStreetMap extracts (Lincoln, the surrounding region, Nebraska highways and rivers) are ODbL:
// © OpenStreetMap contributors https://www.openstreetmap.org/copyright
// Lakes and continental rivers are Natural Earth public-domain data, simplified.
import type { TerrainFeature, TerrainKind } from "./terrain.ts";

type Row = [TerrainKind, number, number[]];

function unpack(rows: Row[]): TerrainFeature[] {
  return rows.map(([kind, rank, flat]) => {
    const coordinates: TerrainFeature["coordinates"] = [];
    for (let i = 0; i < flat.length; i += 2) coordinates.push([flat[i], flat[i + 1]]);
    return { kind, rank, coordinates };
  });
}

